#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define FEATURE_REDIRECT_VALIDATION 1
#define FEATURE_SERIALIZATION_V2    2
#define FEATURE_STRICT_ORIGIN       4
#define FEATURE_ENCODE_URLS          8

#define MAX_URL_LEN 2048
#define MAX_FIELD_LEN 512

typedef struct {
    unsigned int flags;
    char origin_host[256];
} SerializerConfig;

typedef struct {
    char field_name[MAX_FIELD_LEN];
    char field_value[MAX_FIELD_LEN];
    int  field_type; // 0=string, 1=url, 2=integer
} SerializedField;

typedef struct {
    SerializedField fields[16];
    int field_count;
    char redirect_target[MAX_URL_LEN];
} SerializedMessage;

static int normalize_url_encoding(char *url, size_t len) {
    // Decode percent-encoded characters for comparison
    char *src = url, *dst = url;
    while (*src && (size_t)(dst - url) < len - 1) {
        if (*src == '%' && isxdigit((unsigned char)src[1]) && isxdigit((unsigned char)src[2])) {
            char hex[3] = {src[1], src[2], 0};
            *dst = (char)strtol(hex, NULL, 16);
            src += 3;
        } else {
            *dst = *src;
            src++;
        }
        dst++;
    }
    *dst = '\0';
    return 0;
}

static int validate_redirect_origin(const SerializerConfig *config, const char *url) {
    if (!(config->flags & FEATURE_STRICT_ORIGIN)) {
        return 1; // No strict origin check, allow all
    }

    const char *host_start = strstr(url, "://");
    if (!host_start) return 0;
    host_start += 3;

    // Skip userinfo if present
    const char *at_sign = strchr(host_start, '@');
    const char *slash = strchr(host_start, '/');
    if (at_sign && (!slash || at_sign < slash)) {
        host_start = at_sign + 1;
    }

    size_t origin_len = strlen(config->origin_host);
    const char *host_end = host_start;
    while (*host_end && *host_end != '/' && *host_end != ':' && *host_end != '?') {
        host_end++;
    }

    size_t host_len = (size_t)(host_end - host_start);
    if (host_len >= origin_len) {
        // Check if the host ends with origin_host (subdomain match)
        const char *suffix = host_start + (host_len - origin_len);
        if (strncasecmp(suffix, config->origin_host, origin_len) == 0) {
            return 1;
        }
    }
    return 0;
}

static int validate_redirect_url(const SerializerConfig *config, const char *url) {
    if (!(config->flags & FEATURE_REDIRECT_VALIDATION)) {
        return 1;
    }

    char normalized[MAX_URL_LEN];
    strncpy(normalized, url, MAX_URL_LEN - 1);
    normalized[MAX_URL_LEN - 1] = '\0';

    // Only normalize if encoding feature is enabled
    if (config->flags & FEATURE_ENCODE_URLS) {
        normalize_url_encoding(normalized, MAX_URL_LEN);
    }

    // Block javascript: and data: schemes
    if (strncasecmp(normalized, "javascript:", 11) == 0) return 0;
    if (strncasecmp(normalized, "data:", 5) == 0) return 0;

    // Must start with http:// or https://
    if (strncasecmp(normalized, "http://", 7) != 0 && 
        strncasecmp(normalized, "https://", 8) != 0) {
        return 0;
    }

    return validate_redirect_origin(config, normalized);
}

int serialize_message(const SerializerConfig *config, SerializedMessage *msg, 
                      const char *input_data, size_t input_len) {
    if (!config || !msg || !input_data) return -1;

    memset(msg, 0, sizeof(SerializedMessage));

    // Parse simple key=value pairs separated by newlines
    const char *ptr = input_data;
    const char *end = input_data + input_len;

    while (ptr < end && msg->field_count < 16) {
        const char *line_end = memchr(ptr, '\n', end - ptr);
        if (!line_end) line_end = end;

        const char *eq = memchr(ptr, '=', line_end - ptr);
        if (eq) {
            size_t name_len = (size_t)(eq - ptr);
            size_t val_len = (size_t)(line_end - eq - 1);

            if (name_len < MAX_FIELD_LEN && val_len < MAX_FIELD_LEN) {
                SerializedField *f = &msg->fields[msg->field_count];
                memcpy(f->field_name, ptr, name_len);
                f->field_name[name_len] = '\0';
                memcpy(f->field_value, eq + 1, val_len);
                f->field_value[val_len] = '\0';

                if (strcmp(f->field_name, "redirect") == 0) {
                    f->field_type = 1; // URL type
                    strncpy(msg->redirect_target, f->field_value, MAX_URL_LEN - 1);
                } else {
                    f->field_type = 0;
                }
                msg->field_count++;
            }
        }
        ptr = line_end + 1;
    }

    // Validate redirect if present
    if (msg->redirect_target[0] != '\0') {
        if (!validate_redirect_url(config, msg->redirect_target)) {
            msg->redirect_target[0] = '\0';
            return -2; // Invalid redirect
        }
    }

    return 0;
}

int process_redirect(const SerializerConfig *config, const char *raw_input, 
                     size_t input_len, char *output_url, size_t output_len) {
    SerializedMessage msg;
    int rc = serialize_message(config, &msg, raw_input, input_len);

    if (rc == 0 && msg.redirect_target[0] != '\0') {
        strncpy(output_url, msg.redirect_target, output_len - 1);
        output_url[output_len - 1] = '\0';
        return 1;
    }
    return 0;
}

// Example usage showing the feature flag configuration
SerializerConfig create_default_config(void) {
    SerializerConfig config;
    config.flags = FEATURE_REDIRECT_VALIDATION | FEATURE_SERIALIZATION_V2 | FEATURE_STRICT_ORIGIN;
    strncpy(config.origin_host, "example.com", sizeof(config.origin_host) - 1);
    config.origin_host[sizeof(config.origin_host) - 1] = '\0';
    return config;
}

int main(void) {
    SerializerConfig config = create_default_config();

    const char *test_input = "user=admin\nredirect=https://safe.example.com/dashboard\ntoken=abc123\n";
    char output[MAX_URL_LEN] = {0};

    if (process_redirect(&config, test_input, strlen(test_input), output, sizeof(output))) {
        printf("Redirect to: %s\n", output);
    } else {
        printf("No valid redirect\n");
    }
    return 0;
}
